INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('about.paragraphs.0', 'es', 'Soy Luciano Oliva Bianco (Lulox). Vivo en Buenos Aires, Argentina.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('about.paragraphs.1', 'es', 'Con Grok armo dapps y webapps, y automatizaciones sencillas como correo y calendario. Para automatizaciones más específicas uso n8n.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('about.paragraphs.2', 'es', 'Me interesa la adopción cripto a nivel mundial desde que conocí Bitcoin en 2010. Creo que lo que más uso traerá a blockchain es la tokenización, las stablecoins y el comercio agéntico.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('about.paragraphs.3', 'es', 'Soy embajador de Midnight, la blockchain de privacidad de IOG: privacidad selectiva, identidad y smart contracts que pueden probar hechos sin revelar datos de más. La privacidad es lo que permitirá que la tecnología blockchain sea adoptada por personas e instituciones que hoy prefieren no usarla por su transparencia.');
