INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.tokenization.body', 'es', 'Investigo CIP-0113 en Cardano y ERC-3643 / T-REX en EVM: programmable tokens con reglas de transferencia, custody e identidad on-chain. También el status legal de la tokenización en distintos países.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.midnight.title', 'es', 'Midnight Network');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.midnight.summary', 'es', 'Privacy chain · Midnight Ambassador.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.midnight.body', 'es', 'Soy Midnight Ambassador. Midnight es una blockchain enfocada en privacidad selectiva: smart contracts que pueden probar hechos sin revelar datos de más.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.hermes.title', 'es', 'Hermes Agent');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.hermes.summary', 'es', 'Agente autónomo · tools, memoria y workflows.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.hermes.body', 'es', 'Usé Hermes Agent varios meses. Para el día a día pasé a Grok (correo, calendario, builds y MCPs). Sigo explorando Hermes para proyectos futuros: aprende bien y es fuerte para automatizaciones complejas en lenguaje natural.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.lcp.title', 'es', 'LCP');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.lcp.summary', 'es', 'Legal Context Protocol · compliance para agentic commerce.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.lcp.body', 'es', 'Estoy investigando el Legal Context Protocol (LCP): un estándar para que los agentes firmen / acepten contexto legal y de compliance antes de ejecutar microtransacciones. Términos descubribles, verificables y con recourse, para que el agentic commerce no sea un vacío legal.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.x402.title', 'es', 'x402');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.x402.summary', 'es', 'Pagos HTTP-nativos · comercio agéntico.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.x402.body', 'es', 'Investigo x402: el estándar abierto de pagos nativos de internet (HTTP 402 Payment Required) para que agentes y servicios paguen APIs, datos y contenido con stablecoins, sin cuentas ni API keys. La capa de value transfer del comercio agéntico.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.erc8004.title', 'es', 'ERC-8004');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.erc8004.summary', 'es', 'Identidad, reputación y validación de agentes.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.erc8004.body', 'es', 'Investigo ERC-8004 (Trustless Agents): identidad on-chain portable para agentes (registro ERC-721), reputación y hooks de validación. Cómo descubrir y confiar en agentes entre organizaciones sin trust previo. Encaja con x402 y con el resto del stack de agentic commerce.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.punksociety.title', 'es', 'PunkSociety');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.punksociety.body', 'es', 'Red social on-chain: cada post es un NFT y los likes envían valor al creador.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.punksociety.paragraphs.0', 'es', 'PunkSociety es una red social on-chain: cada post es un NFT y los likes envían valor (USDC) al creador. La idea es alinear atención con ownership y pagos directos.');
