INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.title', 'es', 'SAMI');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.body', 'es', 'Juego de chat donde humanos cazan al infiltrado de IA (y la IA se hace pasar por humano).');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.paragraphs.0', 'es', 'SAMI es un juego de chat en el que humanos tienen que encontrar al infiltrado de IA. El agente se camufla entre jugadores y con el tiempo busca ser cada vez más difícil de detectar.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.paragraphs.1', 'es', 'Está construido con TypeScript, Eliza, Next.js, Express, Supabase y un stack web3 (RainbowKit, Foundry, Wagmi, Viem).');
