INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.mochi.paragraphs.0', 'es', 'Mochi son mascotas de IA de escritorio (y browser) con chat, cuerpos custom y un marketplace propio en Avalanche: ownership on-chain, AI off-chain.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.mochi.paragraphs.1', 'es', 'Incluye web app, app Electron y extensiones de Chrome/Firefox, con runtime compartido, contratos en Foundry y metadata en IPFS.');
