INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('about.paragraphs.0', 'en', 'I''m Luciano Oliva Bianco (Lulox). I live in Buenos Aires, Argentina.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('about.paragraphs.1', 'en', 'With Grok I build dapps and webapps, and simple automations like email and calendar. For more specific automations I use n8n.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('about.paragraphs.2', 'en', 'I''ve cared about global crypto adoption since I first learned about Bitcoin in 2010. I think what will drive the most real usage for blockchain is tokenization, stablecoins, and agentic commerce.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('about.paragraphs.3', 'en', 'I''m a Midnight Ambassador for IOG''s privacy blockchain: selective privacy, identity, and smart contracts that can prove facts without oversharing data. Privacy is what will let blockchain be adopted by people and institutions that today prefer not to use it because of how transparent it is.');
