INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.tokenization.title', 'en', 'Tokenization');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.tokenization.summary', 'en', 'Token standards and legal framework.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.tokenization.body', 'en', 'I research both CIP-0113 on Cardano and ERC-3643 / T-REX on EVM: programmable tokens with transfer rules, custody, and on-chain identity. Also the legal status of tokenization across different countries.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.midnight.title', 'en', 'Midnight Network');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.midnight.summary', 'en', 'Privacy chain · Midnight Ambassador.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.midnight.body', 'en', 'I''m a Midnight Ambassador. Midnight is a blockchain focused on selective privacy: smart contracts that can prove facts without leaking more data than needed.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.hermes.title', 'en', 'Hermes Agent');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.hermes.summary', 'en', 'Autonomous agent · tools, memory, and workflows.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.hermes.body', 'en', 'I used Hermes Agent for several months. For day-to-day work I moved to Grok (email, calendar, builds, and MCPs). I still explore Hermes for future projects: it learns well and is strong for complex natural-language automations.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.lcp.title', 'en', 'LCP');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.lcp.summary', 'en', 'Legal Context Protocol · compliance for agentic commerce.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.lcp.body', 'en', 'I''m researching the Legal Context Protocol (LCP): a standard so agents must sign / accept legal and compliance context before running microtransactions. Discoverable, verifiable terms with recourse, so agentic commerce isn''t a legal void.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.x402.title', 'en', 'x402');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.x402.summary', 'en', 'HTTP-native payments · agentic commerce.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.x402.body', 'en', 'I research x402: the open internet-native payment standard (HTTP 402 Payment Required) so agents and services can pay for APIs, data, and content with stablecoins, without accounts or API keys. The value-transfer layer of agentic commerce.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.erc8004.title', 'en', 'ERC-8004');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.erc8004.summary', 'en', 'Agent identity, reputation, and validation.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.focus.erc8004.body', 'en', 'I research ERC-8004 (Trustless Agents): portable on-chain agent identity (ERC-721 registry), reputation, and validation hooks. How to discover and trust agents across organizations without pre-existing trust. It pairs with x402 and the rest of the agentic commerce stack.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.punksociety.title', 'en', 'PunkSociety');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.punksociety.body', 'en', 'On-chain social network: every post is an NFT and likes send value to the creator.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.punksociety.paragraphs.0', 'en', 'PunkSociety is an on-chain social network: every post is an NFT and likes send value (USDC) to the creator. The point is aligning attention with ownership and direct payments.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.punksociety.paragraphs.1', 'en', 'I built it with Scaffold-ETH 2, Foundry, and Next.js.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.punksociety.awards', 'en', '3rd place · Avalanche Summit Hackathon 2024.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.title', 'en', 'SAMI');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.body', 'en', 'Chatroom game where humans hunt the AI infiltrator (and the AI pretends to be human).');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.paragraphs.0', 'en', 'SAMI is a chat game where humans have to find the AI infiltrator. The agent blends into the room and aims to get harder to spot over time.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.paragraphs.1', 'en', 'Built with TypeScript, Eliza, Next.js, Express, Supabase, and a web3 stack (RainbowKit, Foundry, Wagmi, Viem).');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.sami.awards', 'en', 'No formal awards.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.mochi.title', 'en', 'Mochi');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.mochi.body', 'en', 'Desktop AI pets with chat, custom bodies, and their own marketplace.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.mochi.paragraphs.0', 'en', 'Mochi is desktop (and browser) AI pets with chat, custom bodies, and an Avalanche marketplace: on-chain ownership, off-chain AI.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.mochi.paragraphs.1', 'en', 'It includes a web app, Electron desktop, Chrome/Firefox extensions, a shared runtime, Foundry contracts, and IPFS metadata.');
INSERT OR IGNORE INTO site_copy (key, locale, value) VALUES ('projects.past.mochi.awards', 'en', 'No formal awards.');
